import json

def parse_answer(raw):
    if not isinstance(raw, str):
        return None
    try:
        value = json.loads(raw)
    except ValueError:
        return None
    if not isinstance(value, dict) or set(value) != {'answer'} or not isinstance(value['answer'], str) or not value['answer'].strip():
        return None
    return value['answer']

