import json

def paid_answer(state, raw):
    if state != 'completed':
        return None
    try:
        value = json.loads(raw)
    except ValueError:
        value = None
    parsed = value['answer'] if isinstance(value, dict) and set(value) == {'answer'} and isinstance(value['answer'], str) else None
    return parsed if parsed is not None else raw

